package dev.flovex.crates;

import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.command.*;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.block.Action;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.NamespacedKey;
import java.util.*;

public final class CratesMC extends JavaPlugin implements Listener, CommandExecutor {
  private NamespacedKey crateKey;
  private final Map<UUID,String> bindMode=new HashMap<>(), opened=new HashMap<>();
  private final Map<UUID,Inventory> menus=new HashMap<>();
  @Override public void onEnable(){saveDefaultConfig();crateKey=new NamespacedKey(this,"crate-key");getServer().getPluginManager().registerEvents(this,this);getCommand("sc").setExecutor(this);getLogger().info("License-free CratesMC enabled.");}
  private String color(String s){return ChatColor.translateAlternateColorCodes('&',s==null?"":s);}
  private void message(CommandSender s,String text){s.sendMessage(color(getConfig().getString("messages.prefix","&8[&6Crates&8] &r")+text));}
  private boolean admin(CommandSender s){if(s.hasPermission("cratesmc.admin"))return true;message(s,getConfig().getString("messages.no-permission","&cNo permission."));return false;}
  private ConfigurationSection crate(String name){return getConfig().getConfigurationSection("crates."+name.toLowerCase(Locale.ROOT));}
  private Set<String> crateNames(){ConfigurationSection sec=getConfig().getConfigurationSection("crates");return sec==null?Collections.emptySet():sec.getKeys(false);}
  private String keyOf(ItemStack item){if(item==null||!item.hasItemMeta())return null;return item.getItemMeta().getPersistentDataContainer().get(crateKey,PersistentDataType.STRING);}
  private ItemStack makeKey(String crate,int amount){String base="keys."+crate;Material mat;try{mat=Material.valueOf(getConfig().getString(base+".material",getConfig().getString("settings.key-material","WHITE_CANDLE")).toUpperCase(Locale.ROOT));}catch(Exception ex){mat=Material.WHITE_CANDLE;}ItemStack stack=new ItemStack(mat,Math.max(1,Math.min(amount,mat.getMaxStackSize())));ItemMeta meta=stack.getItemMeta();meta.setDisplayName(color(getConfig().getString(base+".name","&f&l%crate% Key").replace("%crate%",crate)));List<String> lore=getConfig().getStringList(base+".lore");if(lore.isEmpty())lore=getConfig().getStringList("settings.key-default-lore");meta.setLore(lore.stream().map(this::color).toList());meta.getPersistentDataContainer().set(crateKey,PersistentDataType.STRING,crate.toLowerCase(Locale.ROOT));stack.setItemMeta(meta);return stack;}
  private ItemStack rewardIcon(ConfigurationSection reward){Material material;try{material=Material.valueOf(reward.getString("material","DIAMOND").toUpperCase(Locale.ROOT));}catch(Exception ex){material=Material.CHEST;}ItemStack item=new ItemStack(material,Math.max(1,Math.min(64,reward.getInt("amount",1))));ItemMeta meta=item.getItemMeta();if(reward.contains("name"))meta.setDisplayName(color(reward.getString("name")));List<String> lore=reward.getStringList("lore");if(!lore.isEmpty())meta.setLore(lore.stream().map(this::color).toList());for(String raw:reward.getStringList("enchantments")){String[] pair=raw.split(":");if(pair.length==2)try{meta.addEnchant(Enchantment.getByName(pair[0].trim().toUpperCase(Locale.ROOT)),Integer.parseInt(pair[1].trim()),true);}catch(Exception ignored){}}item.setItemMeta(meta);return item;}
  private void giveKeys(Player p,String name,int amount){if(crate(name)==null){message(p,getConfig().getString("messages.crate-missing","&cCrate not found."));return;}int remaining=Math.max(1,amount);while(remaining>0){int batch=Math.min(remaining,64);Map<Integer,ItemStack> leftovers=p.getInventory().addItem(makeKey(name,batch));leftovers.values().forEach(it->p.getWorld().dropItemNaturally(p.getLocation(),it));remaining-=batch;}message(p,getConfig().getString("messages.key-received","&aKeys received: %amount% %crate%.").replace("%amount%",String.valueOf(amount)).replace("%crate%",name));}
  private void openMenu(Player p,String name,boolean consumeKey){ConfigurationSection crate=crate(name);ConfigurationSection rewards=crate==null?null:crate.getConfigurationSection("rewards");if(rewards==null||rewards.getKeys(false).isEmpty()){message(p,"&cNo rewards configured for this crate.");return;}if(consumeKey){ItemStack held=p.getInventory().getItemInMainHand();if(name.equalsIgnoreCase(keyOf(held))){if(held.getAmount()>1)held.setAmount(held.getAmount()-1);else p.getInventory().setItemInMainHand(null);}else{held=p.getInventory().getItemInOffHand();if(name.equalsIgnoreCase(keyOf(held))){if(held.getAmount()>1)held.setAmount(held.getAmount()-1);else p.getInventory().setItemInOffHand(null);}else return;}}int rows=Math.max(1,Math.min(6,crate.getInt("rows",3)));Inventory inv=Bukkit.createInventory(null,rows*9,color(crate.getString("title","&8Choose reward")));Map<Integer,String> slotMap=new HashMap<>();for(String id:rewards.getKeys(false)){ConfigurationSection r=rewards.getConfigurationSection(id);if(r==null)continue;int slot=r.getInt("slot",Math.max(0,Integer.parseInt(id)-1));if(slot>=0&&slot<inv.getSize()){inv.setItem(slot,rewardIcon(r));slotMap.put(slot,id);}}p.openInventory(inv);opened.put(p.getUniqueId(),name);menus.put(p.getUniqueId(),inv);getConfig().set("runtime-slotmap."+p.getUniqueId(),slotMap);}
  @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(args.length==0){message(sender,"&f/sc bind <crate> &7Bind a block");message(sender,"&f/sc givekey <player> <crate> <amount>");message(sender,"&f/sc keyall <crate> <amount>");message(sender,"&f/sc realkeygive <player> <crate> <amount>");message(sender,"&f/sc realkeyall <crate> <amount>");message(sender,"&f/sc view <crate>");message(sender,"&f/sc keylist <player>");message(sender,"&f/sc keytake <player> <crate> <amount>");message(sender,"&f/sc keyclear <player>");message(sender,"&f/sc reload");return true;}String sub=args[0].toLowerCase(Locale.ROOT);if(sub.equals("view")){if(args.length<2){message(sender,"&cUsage: /sc view <crate>");return true;}if(sender instanceof Player p){if(crate(args[1])==null)message(p,"&cUnknown crate.");else openMenu(p,args[1],false);}return true;}if(!admin(sender))return true;try{switch(sub){case "bind":if(!(sender instanceof Player p)||args.length<2){message(sender,"&cUsage: /sc bind <crate>");break;}if(crate(args[1])==null){message(sender,"&cUnknown crate.");break;}bindMode.put(p.getUniqueId(),args[1].toLowerCase(Locale.ROOT));message(p,"&aRight-click a block to bind &f"+args[1]+"&a. Sneak-click cancels.");break;
case "givekey":case "realkeygive":if(args.length<4){message(sender,"&cUsage: /sc "+sub+" <player> <crate> <amount>");break;}Player target=Bukkit.getPlayerExact(args[1]);if(target==null){message(sender,"&cPlayer must be online.");break;}giveKeys(target,args[2],Integer.parseInt(args[3]));break;
case "keyall":case "realkeyall":if(args.length<3){message(sender,"&cUsage: /sc "+sub+" <crate> <amount>");break;}for(Player online:Bukkit.getOnlinePlayers())giveKeys(online,args[1],Integer.parseInt(args[2]));break;
case "keytake":if(args.length<4){message(sender,"&cUsage: /sc keytake <player> <crate> <amount>");break;}Player take=Bukkit.getPlayerExact(args[1]);if(take==null){message(sender,"&cPlayer must be online.");break;}int left=Math.max(0,Integer.parseInt(args[3]));for(int i=0;i<take.getInventory().getSize()&&left>0;i++){ItemStack it=take.getInventory().getItem(i);if(it!=null&&args[2].equalsIgnoreCase(keyOf(it))){int remove=Math.min(left,it.getAmount());it.setAmount(it.getAmount()-remove);left-=remove;if(it.getAmount()<=0)take.getInventory().setItem(i,null);}}message(sender,"&aKeys removed.");break;
case "keyclear":if(args.length<2){message(sender,"&cUsage: /sc keyclear <player>");break;}Player clear=Bukkit.getPlayerExact(args[1]);if(clear==null){message(sender,"&cPlayer must be online.");break;}for(int i=0;i<clear.getInventory().getSize();i++){if(keyOf(clear.getInventory().getItem(i))!=null)clear.getInventory().setItem(i,null);}message(sender,"&aKeys cleared.");break;
case "keylist":if(args.length<2){message(sender,"&cUsage: /sc keylist <player>");break;}Player list=Bukkit.getPlayerExact(args[1]);if(list==null){message(sender,"&cPlayer must be online.");break;}message(sender,"&f"+list.getName()+" keys:");for(String id:crateNames()){int count=0;for(ItemStack it:list.getInventory().getContents())if(it!=null&&id.equalsIgnoreCase(keyOf(it)))count+=it.getAmount();message(sender,"&7"+id+": &f"+count);}break;
case "reload":reloadConfig();message(sender,"&aReloaded.");break;
default:message(sender,"&cUnknown subcommand. /sc for help.");}}catch(Exception ex){message(sender,"&cInvalid arguments.");getLogger().warning("Command error: "+ex.getMessage());}return true;}
  @EventHandler public void interact(PlayerInteractEvent e){if(e.getAction()!=Action.RIGHT_CLICK_BLOCK)return;Player p=e.getPlayer();String binding=bindMode.get(p.getUniqueId());Block block=e.getClickedBlock();if(binding!=null){if(p.isSneaking()){bindMode.remove(p.getUniqueId());message(p,"&cBinding cancelled.");return;}if(block!=null){getConfig().set("settings.bound-blocks."+block.getWorld().getName()+"."+block.getX()+"_"+block.getY()+"_"+block.getZ(),binding);saveConfig();bindMode.remove(p.getUniqueId());e.setCancelled(true);message(p,"&aCrate block bound.");}return;}String key=keyOf(e.getItem());if(key!=null&&crate(key)!=null){e.setCancelled(true);openMenu(p,key,true);return;}if(block!=null){String path="settings.bound-blocks."+block.getWorld().getName()+"."+block.getX()+"_"+block.getY()+"_"+block.getZ();String name=getConfig().getString(path);if(name!=null){e.setCancelled(true);openMenu(p,name,false);}}}
  @EventHandler public void click(InventoryClickEvent e){UUID uid=e.getWhoClicked().getUniqueId();Inventory menu=menus.get(uid);if(menu==null||e.getView().getTopInventory()!=menu)return;e.setCancelled(true);int slot=e.getRawSlot();if(slot<0||slot>=menu.getSize())return;Player p=(Player)e.getWhoClicked();String crateName=opened.get(uid);ConfigurationSection crate=crate(crateName);if(crate==null)return;ConfigurationSection rewards=crate.getConfigurationSection("rewards");if(rewards==null)return;String rewardId=null;ConfigurationSection reward=null;for(String rid:rewards.getKeys(false)){ConfigurationSection r=rewards.getConfigurationSection(rid);if(r!=null&&r.getInt("slot",Math.max(0,Integer.parseInt(rid)-1))==slot){rewardId=rid;reward=r;break;}}if(reward==null)return;List<String> commands=reward.getStringList("commands");if(commands.isEmpty()){ItemStack item=rewardIcon(reward);Map<Integer,ItemStack> leftovers=p.getInventory().addItem(item);leftovers.values().forEach(it->p.getWorld().dropItemNaturally(p.getLocation(),it));}else for(String raw:commands)Bukkit.dispatchCommand(Bukkit.getConsoleSender(),raw.replace("%player%",p.getName()));p.closeInventory();message(p,getConfig().getString("messages.crate-opened","&aReward claimed!"));try{p.playSound(p.getLocation(),Sound.valueOf(getConfig().getString("settings.sounds.win","ENTITY_PLAYER_LEVELUP")),1f,1f);}catch(Exception ignored){}}
  @EventHandler public void close(InventoryCloseEvent e){UUID uid=e.getPlayer().getUniqueId();if(menus.get(uid)==e.getView().getTopInventory()){menus.remove(uid);opened.remove(uid);}}
}
